#include <stdint.h>
#include <stdio.h>
#include <string.h>
uint32_t CCPU_FLAGS[32];uint8_t pf_table[256];
extern void XOR(uint32_t*,uint32_t,uint8_t);extern void SUB(uint32_t*,uint32_t,uint8_t);
static int test(unsigned op,unsigned size,uint32_t a,uint32_t b){uint32_t cpu=a,flags=0,out=a,mask=size==8?255u:size==16?65535u:0xffffffffu; a&=mask;b&=mask;cpu=a;out=a;
#define EXEC(inst,suffix,fmt,con) __asm__ volatile(inst suffix " " fmt "," fmt "\n\tpushfl\n\tpopl %1" : "+a"(cpu),"=r"(flags):con(b):"cc")
if(op){SUB(&out,b,(uint8_t)size);if(size==8){__asm__ volatile("subb %b2,%b0; pushfl; popl %1":"+a"(cpu),"=r"(flags):"q"(b):"cc");}else if(size==16){__asm__ volatile("subw %w2,%w0; pushfl; popl %1":"+a"(cpu),"=r"(flags):"r"(b):"cc");}else {__asm__ volatile("subl %2,%0; pushfl; popl %1":"+a"(cpu),"=r"(flags):"r"(b):"cc");}}else{XOR(&out,b,(uint8_t)size);if(size==8){__asm__ volatile("xorb %b2,%b0; pushfl; popl %1":"+a"(cpu),"=r"(flags):"q"(b):"cc");}else if(size==16){__asm__ volatile("xorw %w2,%w0; pushfl; popl %1":"+a"(cpu),"=r"(flags):"r"(b):"cc");}else {__asm__ volatile("xorl %2,%0; pushfl; popl %1":"+a"(cpu),"=r"(flags):"r"(b):"cc");}}
int idx[]={0,2,4,6,7,11};for(unsigned i=0;i<6;i++){int n=idx[i];if(n==4&&!op)continue;if(CCPU_FLAGS[n]!=((flags>>n)&1)){printf("FAIL op=%u size=%u a=%08x b=%08x flag=%d ours=%u native=%u\n",op,size,a,b,n,CCPU_FLAGS[n],(flags>>n)&1);return 1;}}if((out&mask)!=(cpu&mask)||out!=(out&mask)){printf("FAIL value op=%u size=%u a=%08x b=%08x ours=%08x native=%08x\n",op,size,a,b,out,cpu&mask);return 1;}return 0;}
int main(void){uint32_t state=0x89712643;unsigned i,j,op,size;uint64_t count=0;for(i=0;i<256;i++)pf_table[i]=(uint8_t)!__builtin_parity(i);for(op=0;op<2;op++){for(i=0;i<256;i++)for(j=0;j<256;j++){if(test(op,8,i,j))return 1;++count;}for(size=16;size<=32;size*=2){uint32_t edge[]={0,1,0x7f,0x80,0xff,0x100,0x7fff,0x8000,0xffff,0x10000,0x7fffffff,0x80000000,0xffffffff};for(i=0;i<13;i++)for(j=0;j<13;j++){if(test(op,size,edge[i],edge[j]))return 1;++count;}for(i=0;i<100000;i++){state=state*1664525u+1013904223u;uint32_t a=state;state=state*1664525u+1013904223u;if(test(op,size,a,state))return 1;++count;}}}printf("PASS SUB/XOR %llu cases: exhaustive 8-bit pairs, 16/32 edge and seeded samples; defined flags only\n",(unsigned long long)count);return 0;}
